447	std::optional<std::vector<std::string>> FindRoutePath(
448	    const StationCatalog& catalog, const std::string& from, const std::string& to) {
449	  if (from == to) {
450	    return std::vector<std::string>{from};
451	  }
452	
453	  std::vector<std::string> ids;
454	  ids.reserve(catalog.stations.size() + catalog.road_nodes.size());
455	  for (const auto& station : catalog.stations) {
456	    ids.push_back(station.id);
457	  }
458	  // 通行节点与站点共用同一图节点集合，支持途经路口的混合图寻路
459	  for (const auto& road_node : catalog.road_nodes) {
460	    ids.push_back(road_node.id);
461	  }
462	  const auto index_of = [&](const std::string& id) -> std::optional<std::size_t> {
463	    const auto it = std::find(ids.begin(), ids.end(), id);
464	    if (it == ids.end()) {
465	      return std::nullopt;
466	    }
467	    return static_cast<std::size_t>(std::distance(ids.begin(), it));
468	  };
469	
470	  const auto start = index_of(from);
471	  const auto goal = index_of(to);
472	  if (!start.has_value() || !goal.has_value()) {
473	    return std::nullopt;
474	  }
475	
476	  const double infinity = std::numeric_limits<double>::infinity();
477	  std::vector<double> distance(ids.size(), infinity);
478	  std::vector<std::optional<std::size_t>> previous(ids.size(), std::nullopt);
479	  std::vector<bool> visited(ids.size(), false);
480	  distance[*start] = 0.0;
481	
482	  for (std::size_t iteration = 0; iteration < ids.size(); ++iteration) {
483	    std::optional<std::size_t> current;
484	    for (std::size_t i = 0; i < ids.size(); ++i) {
485	      if (!visited[i] && (!current.has_value() || distance[i] < distance[*current])) {
486	        current = i;
487	      }
488	    }
489	    if (!current.has_value() || !std::isfinite(distance[*current])) {
490	      break;
491	    }
492	    if (*current == *goal) {
493	      break;
494	    }
495	    visited[*current] = true;
496	
497	    for (const auto& edge : catalog.edges) {
498	      if (!edge.enabled) {
499	        continue;
500	      }
501	      const auto edge_from = index_of(edge.from);
502	      const auto edge_to = index_of(edge.to);
503	      if (!edge_from.has_value() || !edge_to.has_value()) {
504	        continue;
505	      }
506	      auto relax = [&](const std::size_t source, const std::size_t target) {
507	        if (source == *current && distance[source] + edge.distance_m < distance[target]) {
508	          distance[target] = distance[source] + edge.distance_m;
509	          previous[target] = source;
510	        }
511	      };
512	      relax(*edge_from, *edge_to);
513	      if (edge.bidirectional) {
514	        relax(*edge_to, *edge_from);
515	      }
516	    }
517	  }
518	  if (!std::isfinite(distance[*goal])) {
519	    return std::nullopt;
520	  }
521	  std::vector<std::string> path;
522	  for (auto current = *goal;;) {
523	    path.push_back(ids[current]);
524	    if (current == *start) {
525	      break;
526	    }
527	    if (!previous[current].has_value()) {
528	      return std::nullopt;
529	    }
530	    current = *previous[current];
531	  }
532	  std::reverse(path.begin(), path.end());
533	  return path;
534	}
