536	bool ValidateStationCatalog(const StationCatalog& catalog, std::string* message) {
537	  if (catalog.stations.empty()) {
538	    if (message != nullptr) {
539	      *message = "station catalog is empty";
540	    }
541	    return false;
542	  }
543	
544	  std::unordered_set<std::string> ids;
545	  for (const auto& station : catalog.stations) {
546	    if (station.id.empty()) {
547	      if (message != nullptr) {
548	        *message = "station id is empty";
549	      }
550	      return false;
551	    }
552	    if (station.frame_id.empty()) {
553	      if (message != nullptr) {
554	        *message = "station frame_id is empty: " + station.id;
555	      }
556	      return false;
557	    }
558	    if (!std::isfinite(station.x) || !std::isfinite(station.y) || !std::isfinite(station.yaw)) {
559	      if (message != nullptr) {
560	        *message = "station pose is not finite: " + station.id;
561	      }
562	      return false;
563	    }
564	    if (!ids.insert(station.id).second) {
565	      if (message != nullptr) {
566	        *message = "duplicate station id: " + station.id;
567	      }
568	      return false;
569	    }
570	  }
571	
572	  // road_nodes 与 stations 共用同一 id 空间：集合内与跨集合均不允许重复
573	  for (const auto& road_node : catalog.road_nodes) {
574	    if (road_node.id.empty()) {
575	      if (message != nullptr) {
576	        *message = "road node id is empty";
577	      }
578	      return false;
579	    }
580	    if (road_node.frame_id.empty()) {
581	      if (message != nullptr) {
582	        *message = "road node frame_id is empty: " + road_node.id;
583	      }
584	      return false;
585	    }
586	    if (!std::isfinite(road_node.x) || !std::isfinite(road_node.y) ||
587	        !std::isfinite(road_node.yaw)) {
588	      if (message != nullptr) {
589	        *message = "road node pose is not finite: " + road_node.id;
590	      }
591	      return false;
592	    }
593	    if (!ids.insert(road_node.id).second) {
594	      if (message != nullptr) {
595	        *message = "duplicate road node id: " + road_node.id;
596	      }
597	      return false;
598	    }
599	  }
600	
601	  for (const auto& edge : catalog.edges) {
602	    if (edge.from.empty() || edge.to.empty()) {
603	      if (message != nullptr) {
604	        *message = "station edge endpoint is empty";
605	      }
606	      return false;
607	    }
608	    if (ids.find(edge.from) == ids.end()) {
609	      if (message != nullptr) {
610	        *message = "station edge has unknown from endpoint: " + edge.from;
611	      }
612	      return false;
613	    }
614	    if (ids.find(edge.to) == ids.end()) {
615	      if (message != nullptr) {
616	        *message = "station edge has unknown to endpoint: " + edge.to;
617	      }
618	      return false;
619	    }
620	    if (!std::isfinite(edge.distance_m) || edge.distance_m < 0.0) {
621	      if (message != nullptr) {
622	        *message = "station edge distance is invalid: " + edge.from + " -> " + edge.to;
623	      }
624	      return false;
625	    }
626	    for (const auto& point : edge.polyline) {
627	      if (!std::isfinite(point.first) || !std::isfinite(point.second)) {
628	        if (message != nullptr) {
629	          *message = "station edge polyline point is not finite: " + edge.from + " -> " + edge.to;
630	        }
631	        return false;
632	      }
633	    }
634	  }
635	
636	  if (message != nullptr) {
637	    *message = "ok";
638	  }
639	  return true;
640	}
